Here is the commit message:
ALSA: usb-audio: Avoid potential endless loop in
 convert_chmap_v3()

The convert_chmap_v3() has a loop with its increment size of
cs_desc->wLength, but we forgot to validate cs_desc->wLength itself,
which may lead to potential endless loop by a malformed descriptor.

Add a proper size check to abort the loop for plugging the hole.

Fixes: ecfd41166b72 ("ALSA: usb-audio: Validate UAC3 cluster segment descriptors")
Cc: <stable@vger.kernel.org>
Link: https://patch.msgid.link/20260427152224.15276-1-tiwai@suse.de
Signed-off-by: Takashi Iwai <tiwai@suse.de>

Here is the root cause:
The function convert_chmap_v3() iterates over UAC3 cluster segment descriptors using cs_desc->wLength as the loop increment. However, before this patch, there was no validation that cs_desc->wLength is at least sizeof(*cs_desc). A malformed descriptor with a too-small wLength could cause the loop to either not advance or advance incorrectly, potentially resulting in an infinite loop.

Here is the patch:
 /* UAC3 device stores channels information in Cluster Descriptors */
 static struct
 snd_pcm_chmap_elem *convert_chmap_v3(struct uac3_cluster_header_descriptor
 								*cluster)
 {
 	unsigned int channels = cluster->bNrChannels;
 	struct snd_pcm_chmap_elem *chmap;
 	void *p = cluster;
 	int len, c;

 	if (channels > ARRAY_SIZE(chmap->map))
 		return NULL;

 	chmap = kzalloc_obj(*chmap);
 	if (!chmap)
 		return NULL;

 	len = le16_to_cpu(cluster->wLength);
 	c = 0;
 	p += sizeof(*cluster);
 	len -= sizeof(*cluster);

 	while (len > 0 && (c < channels)) {
 		struct uac3_cluster_segment_descriptor *cs_desc = p;
 		u16 cs_len;
 		u8 cs_type;

 		if (len < sizeof(*cs_desc))
 			break;
 		cs_len = le16_to_cpu(cs_desc->wLength);
+		if (cs_len < sizeof(*cs_desc))
+			break;
 		if (len < cs_len)
 			break;
 		cs_type = cs_desc->bSegmentType;

 		if (cs_type == UAC3_CHANNEL_INFORMATION) {
 			struct uac3_cluster_information_segment_descriptor *is = p;
 			unsigned char map;

 			if (cs_len < sizeof(*is))
 				break;

 			/*
 			 * TODO: this conversion is not complete, update it
 			 * after adding UAC3 values to asound.h
 			 * NOTE: not all UAC3 channel relationship have a
 			 * direct ALSA chmap equivalent.
 			 */
 			switch (is->bChRelationship) {
 			case UAC3_CH_MONO:
 				map = SNDRV_CHMAP_MONO;
 				break;
 			case UAC3_CH_LEFT:
 			case UAC3_CH_FRONT_LEFT:
 			case UAC3_CH_HEADPHONE_LEFT:
 				map = SNDRV_CHMAP_FL;
 				break;
 			case UAC3_CH_RIGHT:
 			case UAC3_CH_FRONT_RIGHT:
 			case UAC3_CH_HEADPHONE_RIGHT:
 				map = SNDRV_CHMAP_FR;
 				break;
 			case UAC3_CH_FRONT_CENTER:
 				map = SNDRV_CHMAP_FC;
 				break;
 			case UAC3_CH_FRONT_LEFT_OF_CENTER:
 				map = SNDRV_CHMAP_FLC;
 				break;
 			case UAC3_CH_FRONT_RIGHT_OF_CENTER:
 				map = SNDRV_CHMAP_FRC;
 				break;
 			case UAC3_CH_FRONT_WIDE_LEFT:
 				map = SNDRV_CHMAP_FLW;
 				break;
 			case UAC3_CH_FRONT_WIDE_RIGHT:
 				map = SNDRV_CHMAP_FRW;
 				break;
 			case UAC3_CH_SIDE_LEFT:
 				map = SNDRV_CHMAP_SL;
 				break;
 			case UAC3_CH_SIDE_RIGHT:
 				map = SNDRV_CHMAP_SR;
 				break;
 			case UAC3_CH_BACK_LEFT:
 				map = SNDRV_CHMAP_RL;
 				break;
 			case UAC3_CH_BACK_RIGHT:
 				map = SNDRV_CHMAP_RR;
 				break;
 			case UAC3_CH_BACK_CENTER:
 				map = SNDRV_CHMAP_RC;
 				break;
 			case UAC3_CH_BACK_LEFT_OF_CENTER:
 				map = SNDRV_CHMAP_RLC;
 				break;
 			case UAC3_CH_BACK_RIGHT_OF_CENTER:
 				map = SNDRV_CHMAP_RRC;
 				break;
 			case UAC3_CH_TOP_CENTER:
 				map = SNDRV_CHMAP_TC;
 				break;
 			case UAC3_CH_TOP_FRONT_LEFT:
 				map = SNDRV_CHMAP_TFL;
 				break;
 			case UAC3_CH_TOP_FRONT_RIGHT:
 				map = SNDRV_CHMAP_TFR;
 				break;
 			case UAC3_CH_TOP_FRONT_CENTER:
 				map = SNDRV_CHMAP_TFC;
 				break;
 			case UAC3_CH_TOP_FRONT_LOC:
 				map = SNDRV_CHMAP_TFLC;
 				break;
 			case UAC3_CH_TOP_FRONT_ROC:
 				map = SNDRV_CHMAP_TFRC;
 				break;
 			case UAC3_CH_TOP_SIDE_LEFT:
 				map = SNDRV_CHMAP_TSL;
 				break;
 			case UAC3_CH_TOP_SIDE_RIGHT:
 				map = SNDRV_CHMAP_TSR;
 				break;
 			case UAC3_CH_TOP_BACK_LEFT:
 				map = SNDRV_CHMAP_TRL;
 				break;
 			case UAC3_CH_TOP_BACK_RIGHT:
 				map = SNDRV_CHMAP_TRR;
 				break;
 			case UAC3_CH_TOP_BACK_CENTER:
 				map = SNDRV_CHMAP_TRC;
 				break;
 			case UAC3_CH_BOTTOM_CENTER:
 				map = SNDRV_CHMAP_BC;
 				break;
 			case UAC3_CH_LOW_FREQUENCY_EFFECTS:
 				map = SNDRV_CHMAP_LFE;
 				break;
 			case UAC3_CH_LFE_LEFT:
 				map = SNDRV_CHMAP_LLFE;
 				break;
 			case UAC3_CH_LFE_RIGHT:
 				map = SNDRV_CHMAP_RLFE;
 				break;
 			case UAC3_CH_RELATIONSHIP_UNDEFINED:
 			default:
 				map = SNDRV_CHMAP_UNKNOWN;
 				break;
 			}
 			chmap->map[c++] = map;
 		}
 		p += cs_len;
 		len -= cs_len;
 	}

 	if (channels < c)
 		pr_err("%s: channel number mismatch\n", __func__);

 	chmap->channels = channels;

 	for (; c < channels; c++)
 		chmap->map[c] = SNDRV_CHMAP_UNKNOWN;

 	return chmap;
 }



